// Web manifest (Phase 5b): installs the ledger to a phone home screen with the 192/512 px icons
// generated by app/icon.tsx.
import type { MetadataRoute } from "next";

import { tokenColor } from "@/lib/brand/palette";
import { copy } from "@/lib/copy";

export default function manifest(): MetadataRoute.Manifest {
  return {
    name: copy.site.name,
    short_name: copy.site.shortName,
    description: copy.site.description,
    start_url: "/",
    display: "standalone",
    background_color: tokenColor("paper"),
    theme_color: tokenColor("plum"),
    icons: [192, 512].map((s) => ({
      src: `/icon/${s}`,
      sizes: `${s}x${s}`,
      type: "image/png",
      purpose: "any",
    })),
  };
}
